"""Independent original-source upper force/work reconstruction on actual P1 tetra."""
import sys,json,shutil,numpy as np
from baseline_registry import ROOT,REPO,ref,sha,dump
src=ROOT/'validation/integrated'/sys.argv[1];out=ROOT/'validation/integrated'/sys.argv[2];out.mkdir();shutil.copyfile(__file__,out/'producer.py');s=json.loads((src/'summary.json').read_text());a=np.load(src/'field.npz');up=REPO/s['frozen_upper_points']['path'];assert sha(up)==s['frozen_upper_points']['SHA256'];sources=json.loads(up.read_text());maps=json.loads((src/'upper_pullback.json').read_text())['ports'];p=a['points_mm'];t=a['tetra'];F=a['load_N'];u=a['displacement_mm'];vol=abs(np.linalg.det(p[t[:,1:]]-p[t[:,0,None]]))/6;lump=np.zeros(len(p))
for j in range(4):np.add.at(lump,t[:,j],vol/4)
