for q,m in zip(sources,maps):
 assert q['label']==m['label'];mp=REPO/m['mapping']['path'];assert sha(mp)==m['mapping']['SHA256'];b=np.load(mp);ns=b['nodes'];bc=b['barycentric'];force=b['integrated_force_N'];xyz=b['point_mm'];assert np.array_equal(xyz,np.array(q['points_mm'])) and np.array_equal(force,np.array(q['integrated_force_N']));local=np.zeros_like(F)
 for j in range(3):np.add.at(local,ns[:,j],bc[:,j,None]*force)
 calc+=local;vpoint=np.einsum('ni,nij->nj',bc,u[ns]);workq=float(np.sum(vpoint*force));workn=float(np.sum(u*local));W=np.r_[local.sum(0),np.cross(p,local).sum(0)];r=dict(label=q['label'],points=len(ns),all_real_boundary_triangles=all(tuple(k) in fset for k in np.sort(ns,axis=1)),minimum_shape_weight=float(bc.min()),partition_error=float(abs(bc.sum(1)-1).max()),point_geometry_error_mm=float(abs(np.einsum('ni,nij->nj',bc,p[ns])-xyz).max()),wrench_error_N_Nmm=float(abs(W-q['target_N_Nmm']).max()),quadrature_virtual_work_Nmm=workq,nodal_virtual_work_Nmm=workn,work_adjoint_error_Nmm=abs(workq-workn));rows.append(r)
checks=dict(actual_original_source_points_forces=True,all_original_boundary_triangles=all(r['all_real_boundary_triangles'] for r in rows),all_positive_shape_weights=all(r['minimum_shape_weight']>=-1e-10 for r in rows),all_partition_geometry=all(r['partition_error']<1e-12 and r['point_geometry_error_mm']<1e-8 for r in rows),all_wrenches=all(r['wrench_error_N_Nmm']<1e-8 for r in rows),all_virtual_work=all(r['work_adjoint_error_Nmm']<1e-10 for r in rows),actual_full_load_reconstruction=float(abs(calc-F).max())<1e-10,perturbed_load_rejected=float(abs((calc-F).ravel()[0]+.01))>.009)
dump(out/'summary.json',dict(status='ACTUAL_P1_FIXED_UPPER_SOURCE_LOAD_AND_WORK_AUDIT' if all(checks.values()) else 'ACTUAL_P1_FIXED_UPPER_AUDIT_FAIL',candidate=s['candidate'],source=ref(src/'summary.json'),producer=ref(out/'producer.py'),checks=checks,ports=rows,max_nodal_load_error_N=float(abs(calc-F).max()),gravity_force_N=float(calc[:,2].sum()-sum(np.array(q['integrated_force_N'])[:,2].sum() for q in sources)),whole_system_release=False,newly_qualified_system_gate_ids=[],scope='Actualfullplate finiteCADface prescribedupperload interpolation,sourceforce/moment/work identity. NOT actual uppercontact/83body equilibrium.'))
